import { isExternalUrl } from "../utils/external-url.js";
import { matchRewrite } from "../config/config-matchers.js";
//#region src/client/client-rewrite-matcher.ts
function matchClientRewrite(pathname, rewrite, context, basePathState) {
	const destination = matchRewrite(pathname, [{
		source: rewrite.source,
		destination: rewrite.destination ?? "/",
		has: rewrite.has,
		locale: rewrite.locale,
		basePath: rewrite.basePath
	}], context, basePathState);
	if (destination === null) return null;
	if (rewrite.requiresServerEvaluation || isExternalUrl(destination)) return { kind: "server" };
	return {
		kind: "rewrite",
		destination
	};
}
//#endregion
export { matchClientRewrite };
